#[test]
fn every_asymmetric_field_has_an_explicit_policy() {
    let actual: Vec<_> = Field::ALL
        .into_iter()
        .filter(|&f| {
            FieldLayout::Vanilla5875.resolve(f).is_some()
                != FieldLayout::Wrath12340.resolve(f).is_some()
        })
        .collect();
    let listed: Vec<_> = ASYMMETRIC_POLICY.iter().map(|&(f, _, _)| f).collect();
    assert_eq!(
        actual, listed,
        "new layout-only fields need explicit policy review"
    );
    for &(field, absent, policy) in ASYMMETRIC_POLICY {
        assert_eq!(absent.resolve(field), None, "{field:?}");
        assert!(!policy.is_empty(), "{field:?}");
    }
}
